#include <array>
#include <cstddef>
#include <cstdint>
namespace {constexpr int N=64,MAX_ARCS=N*(N-1);void put(std::uint8_t*out,std::size_t i,std::int64_t v){auto b=static_cast<std::uint64_t>(v);for(int j=0;j<8;++j)out[i*8+j]=static_cast<std::uint8_t>(b>>(8*j));}}
extern "C" std::int64_t bidirectional_search(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap){if(!in||len<4||in[0]<1||in[0]>N)return -1;int n=static_cast<int>(in[0]);if(in[1]<0||in[1]>=n||in[2]<0||in[2]>=n||in[3]<0||in[3]>MAX_ARCS||len!=4+2*static_cast<std::size_t>(in[3]))return -1;
 std::array<std::array<int,N-1>,N>adj{};std::array<int,N>deg{};std::array<std::array<bool,N>,N>edge{};for(int i=0;i<in[3];++i){auto u=in[4+2*i],v=in[5+2*i];if(u<0||u>=n||v<0||v>=n||u==v||edge[u][v])return -1;edge[u][v]=true;adj[u][deg[u]++]=static_cast<int>(v);}for(int u=0;u<n;++u)for(int v=0;v<n;++v)if(edge[u][v]!=edge[v][u])return -1;
 std::array<int,N>path{};int pc=0,start=static_cast<int>(in[1]),goal=static_cast<int>(in[2]);if(start==goal)path[pc++]=start;else{std::array<std::array<int,N>,2>parent{};for(auto&row:parent)row.fill(-2);std::array<std::array<int,N>,2>q{};std::array<int,2>head{},tail{};parent[0][start]=parent[1][goal]=-1;q[0][tail[0]++]=start;q[1][tail[1]++]=goal;int meet=-1;while(head[0]<tail[0]&&head[1]<tail[1]&&meet<0){for(int s=0;s<2&&meet<0;++s){int cur=q[s][head[s]++];for(int j=0;j<deg[cur];++j){int v=adj[cur][j];if(parent[s][v]!=-2)continue;parent[s][v]=cur;q[s][tail[s]++]=v;if(parent[1-s][v]!=-2){meet=v;break;}}}}if(meet>=0){std::array<int,N>rev{};int k=0;for(int v=meet;v!=-1;v=parent[0][v])rev[k++]=v;for(int i=k-1;i>=0;--i)path[pc++]=rev[i];for(int v=parent[1][meet];v!=-1;v=parent[1][v])path[pc++]=v;}}
 auto bytes=static_cast<std::size_t>(1+pc)*8;if(!out||cap<bytes)return -2;put(out,0,pc);for(int i=0;i<pc;++i)put(out,1+i,path[i]);return static_cast<std::int64_t>(bytes);}
